-- =====================================================================
-- Migration 105: تعديل قانون الضريبة على الدخل 91/2005 بموجب
--                        القانون رقم 30 لسنة 2023
-- =====================================================================
--
-- سابع عشرة هجرة فى سلسلة تعديلات قانون 91/2005 نفسه (بعد 084: 181/2005،
--   085: 1/2007، 086: 101/2012، 087: 11/2013، 088: 164/2013، 090:
--   53/2014، 091: 201/2014، 092: 17/2015، 093: 96/2015، 095: 82/2017،
--   096: 76/2017، 097: 29/2018، 098: 97/2018، 099: 158/2018، 100:
--   10/2019، 101: 26/2020). أولى أربع هجرات اكتُشفت حديثًا أثناء رفع
--   القانون 206/2020 ومراجعة إحالاته (105: 30/2023 ← 106: 175/2023 ←
--   107: 7/2024 ← 108: 151/2026، بالترتيب الزمنى الصحيح).
--
-- المصدر: الجريدة الرسمية، العدد 24 مكرر (تابع)، 15 يونيو 2023، صفحات
--   3-22 (20 صفحة) - أضخم وأشمل قانون تعديل فى هذه السلسلة كاملة.
--   قراءة بصرية كاملة لجميع الصفحات العشرين + تكبير x4 مخصص على صفحة 14
--   للتحقق الدقيق من نصى (52/بند1) و(56/فقرة ثالثة) - راجع التوثيق
--   الكامل لملاحظات التدقيق الحرجة فى law_30_2023_amendments.py.
--
-- 29 عملية (17 استبدال + 4 إضافة + 8 إلغاء) - المادتان الأولى والثانية
--   (استبدال/إضافة) والمادة الثامنة (إلغاء) من هذا القانون. أبرز
--   التغييرات الجوهرية:
--   • المادة (8): رابع استبدال لجدول الشرائح، إضافة شريحة إعفاء جزئى
--     2.5% وإغلاق فجوة شريحة 900000-1200000.
--   • المادة (13/بند1): رفع الإعفاء الشخصى من 9000 إلى 15000 جنيه.
--   • المادة (52/بند1): تخفيض نسبة الرسملة الضعيفة من 4:1 إلى 2:1
--     (مخفَّف تدريجيًا بحكم مستقل غير مبنى هنا حتى 2028).
--   • المادة (56/فقرة ثالثة): إسقاط إعفاء قروض القطاعين العام والخاص.
--   • المادة (50): توسيع الإعفاءات من 10 إلى 18 بندًا.
--   • إضافة (46 مكررًا7) - مادة ستُلغَى لاحقًا بالقانون 151/2026
--     (migration 108) - دورة حياة كاملة موثَّقة عبر هجرتين.
--   • إلغاء المادة (11) + المواد (140-146) = 8 مواد (تحقق من وجودها
--     الفعلى فى DB قبل البناء).
--
-- أحكام مستقلة موثَّقة فقط دون بناء (حسب نمط المشروع المُتَّبع لكل حكم
--   انتقالى لا يعدِّل نص مادة مرقَّمة بعينها): المواد الثالثة، الرابعة،
--   الخامسة (تدرج نسبة 52/1)، السادسة (استمرار إعفاء 56 القديم للقروض
--   القائمة)، السابعة، الحادية عشرة. كما لم تُبنَ المادة التاسعة (إلغاء
--   فقرة فى قانون 182/2020 - خارج نطاق قانون 91/2005).
--
-- نفاذ متعدد المسارات (المادة العاشرة): الحكم العام = اليوم التالى
--   للنشر (2023-06-16) لمعظم العمليات؛ المادتان (8) و(13/بند1) = أول
--   الشهر التالى (2023-07-01)؛ (72 مكررًا) الجديدة = أول يناير التالى
--   (2024-01-01)؛ إلغاء المادة (11) تحديدًا = أول يناير التالى أيضًا
--   (نص خاص فى المادة الثامنة) - effective_from مُحدَّد لكل عملية على
--   حدة فى law_30_2023_amendments.py.
--
-- نفس القرار المعمارى المُثبَّت فى كل هجرات هذه السلسلة (UPDATE مباشر).
--
-- قابلة لإعادة التشغيل بأمان (idempotent) - UPDATE/INSERT/repeal بقيم ثابتة.
--
-- =====================================================================

BEGIN;

-- ===== عمليات التعديل =====
-- مادة 1 (suffix=0) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_1$فى تطبيق أحكام هذا القانون يقصد بالألفاظ والعبارات التالية المعنى المبين أمام كل منها :
- الضريبة : الضريبة على الدخل .
- الوزير : وزير المالية .
- رئيس المصلحة : رئيس مصلحة الضرائب العامة .
- المصلحة : مصلحة الضرائب العامة .
- الممول : الشخص الطبيعى أو الشخص الاعتبارى الخاضع للضريبة وفقًا لأحكام هذا القانون .
- شركات الأموال : شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة .
- شركات الأشخاص : شركات التضامن وشركات التوصية البسيطة .
- شركة الواقع : الشركة التي تقوم أو تستمر بين أشخاص طبيعيين دون استيفاء إجراءات الانعقاد أو الشهر ، ولا تعد شركة واقع المنشأة الفردية التي آلت بالميراث على أن يقدم عنها إقرار واحد مضمنًا حصة كل وارث فيها .
- المشروع : الكيان الاقتصادى الذى يزاول النشاط الأصلى فى مصر أو المنشأة الدائمة فى مصر التابعة لكيان اقتصادى فى الخارج .
- الشخص المرتبط : كل شخص يرتبط بممول بعلاقة تؤثر في تحديد وعاء الضريبة بشكل مباشر أو غير مباشر ، سواء من خلال الإدارة أو السيطرة أو الملكية ، وبوجه عام يكون الشخصان مرتبطين إذا كانت العلاقة بينهما تصل إلى حد إمكانية قيام أحدهما بالتصرف وفقًا لتوجيهات ، أو طلبات ، أو اقتراحات ، أو إرادة الشخص الآخر ، أو شخص ثالث .
ويعامل الأشخاص التالي ذكرهم بوصفهم أشخاصًا مرتبطين :
1- الزوج والزوجة والأصول والفروع .
2- شركة الأشخاص والشركاء المتضامنون والموصون فيها .
3- شركة الأموال والشخص الذي يملك فيها بشكل مباشر أو غير مباشر (50%) على الأقل من حقوق التصويت أو الإدارة في الشركة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال .
4- أي شركتين أو أكثر يملك شخص آخر (50%) أو أكثر على الأقل من حقوق التصويت أو الإدارة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال في الشركتين أو أكثر .
وعند تطبيق البندين 2 أو 3 أو 4 من الفقرة السابقة ، فإن الحيازة التي تنسب إلى شخص ما من قبل شخص مرتبط لا يجوز أن تنسب إلى شخص آخر مرتبط .
لا يعتبر شخصان مرتبطين لمجرد أن أحدهما يعد عاملاً أو عميلاً لدى الشخص الآخر أو أن كليهما يعد عاملاً أو عميلاً لدى شخص ثالث ، ما لم يؤثر هذا الارتباط بشكل مباشر أو غير مباشر فى تحديد وعاء الضريبة .
- السعر المحايد : السعر الذى يتم التعامل بمقتضاه بين شخصين غير مرتبطين أو أكثر ، ويتحدد وفقًا لقوى السوق وظروف التعامل .
- الإتاوات : المبالغ المدفوعة أيًا كان نوعها مقابل استعمال أو الحق أو الحق فى استعمال حقوق النشر الخاصة بعمل أدبى أو فنى أو علمى بما فى ذلك أفلام السينما ، أو براءة اختراع أو علامة تجارية أو تصميم أو نموذج أو خطة أو تركيبة أو عملية سرية أو مقابل استعمال أو الحق فى استعمال معدات صناعية أو تجارية أو علمية أو معلومات متعلقة بالخبرة الصناعية أو التجارية أو العلمية .
- توزيعات الأرباح : أى دخل مستمد من الأسهم أو الحصص ، بما فى ذلك أسهم التمتع أو حقوق التمتع ، وأسهم التعدين ، وأسهم التأسيس ، وأية حقوق أخرى تعطى حق المشاركة فى الأرباح ، سواء كانت هذه التوزيعات نقدية أو أسهم مجانية أو على شكل سندات أو حصص تأسيس أو على أية صورة أخرى .
$b105_1$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 1 AND article_suffix_order = 0;

UPDATE article_versions SET
    body = $b105_1$فى تطبيق أحكام هذا القانون يقصد بالألفاظ والعبارات التالية المعنى المبين أمام كل منها :
- الضريبة : الضريبة على الدخل .
- الوزير : وزير المالية .
- رئيس المصلحة : رئيس مصلحة الضرائب العامة .
- المصلحة : مصلحة الضرائب العامة .
- الممول : الشخص الطبيعى أو الشخص الاعتبارى الخاضع للضريبة وفقًا لأحكام هذا القانون .
