- شركات الأشخاص : شركات التضامن وشركات التوصية البسيطة .
- شركة الواقع : الشركة التي تقوم أو تستمر بين أشخاص طبيعيين دون استيفاء إجراءات الانعقاد أو الشهر ، ولا تعد شركة واقع المنشأة الفردية التي آلت بالميراث على أن يقدم عنها إقرار واحد مضمنًا حصة كل وارث فيها .
