ويعامل الأشخاص التالي ذكرهم بوصفهم أشخاصًا مرتبطين :
1- الزوج والزوجة والأصول والفروع .
2- شركة الأشخاص والشركاء المتضامنون والموصون فيها .
3- شركة الأموال والشخص الذي يملك فيها بشكل مباشر أو غير مباشر (50%) على الأقل من حقوق التصويت أو الإدارة في الشركة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال .
4- أي شركتين أو أكثر يملك شخص آخر (50%) أو أكثر على الأقل من حقوق التصويت أو الإدارة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال في الشركتين أو أكثر .
وعند تطبيق البندين 2 أو 3 أو 4 من الفقرة السابقة ، فإن الحيازة التي تنسب إلى شخص ما من قبل شخص مرتبط لا يجوز أن تنسب إلى شخص آخر مرتبط .
لا يعتبر شخصان مرتبطين لمجرد أن أحدهما يعد عاملاً أو عميلاً لدى الشخص الآخر أو أن كليهما يعد عاملاً أو عميلاً لدى شخص ثالث ، ما لم يؤثر هذا الارتباط بشكل مباشر أو غير مباشر فى تحديد وعاء الضريبة .
- السعر المحايد : السعر الذى يتم التعامل بمقتضاه بين شخصين غير مرتبطين أو أكثر ، ويتحدد وفقًا لقوى السوق وظروف التعامل .
- الإتاوات : المبالغ المدفوعة أيًا كان نوعها مقابل استعمال أو الحق أو الحق فى استعمال حقوق النشر الخاصة بعمل أدبى أو فنى أو علمى بما فى ذلك أفلام السينما ، أو براءة اختراع أو علامة تجارية أو تصميم أو نموذج أو خطة أو تركيبة أو عملية سرية أو مقابل استعمال أو الحق فى استعمال معدات صناعية أو تجارية أو علمية أو معلومات متعلقة بالخبرة الصناعية أو التجارية أو العلمية .
- توزيعات الأرباح : أى دخل مستمد من الأسهم أو الحصص ، بما فى ذلك أسهم التمتع أو حقوق التمتع ، وأسهم التعدين ، وأسهم التأسيس ، وأية حقوق أخرى تعطى حق المشاركة فى الأرباح ، سواء كانت هذه التوزيعات نقدية أو أسهم مجانية أو على شكل سندات أو حصص تأسيس أو على أية صورة أخرى .
$b105_1$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_1$استبدال تعريفى (شركة الواقع) و(الشخص المرتبط) فقط بموجب القانون 30/2023 (المادة الأولى)، مع بقاء باقى التعريفات كما هى؛ إضافة معايير ونطاقات تفصيلية جديدة (4 بنود) لتعريف الشخص المرتبط لم تكن موجودة من قبل.$n105_1$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 1 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 3 (suffix=0) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_2$يشمل الدخل المحقق من مصدر فى مصر فى مصر ما يأتى :
(أ) الدخل من الخدمات التى تؤدى بها فى مصر ، بما فى ذلك المرتبات وما فى حكمها .
(ب) الدخل الذي يتحمله رب عمل مقيم في مصر ، ولو أدى العمل في الخارج .
(جـ) الدخل الذى يحصل عليه الرياضى أو الفنان من النشاط الذى يقوم به فى مصر .
(د) الدخل من الأعمال التى يؤديها غير المقيم من خلال منشأة دائمة فى مصر .
(هـ) الدخل من التصرفات فى المنقولات التى تخص منشأة دائمة فى مصر .
(و) الدخل من الاستغلال والتصرف فى العقارات وما فى حكمها الكائنة بمصر وما يلحق بها من عقارات بالتخصيص .
(ز) التوزيعات على أسهم شركة أموال مقيمة فى مصر .
(ح) حصص الأرباح التى تدفعها شركة أشخاص مقيمة فى مصر .
(ط) العائد الذى تدفعه الحكومة أو وحدات الإدارة المحلية أو الأشخاص الاعتبارية العامة أو أى شخص مقيم فى مصر ، والعائد الذى يتم سداده من منشأة دائمة فى مصر ولو كان مالكها غير مقيم فيها .
(ى) مبالغ الإيجار ورسوم الترخيص والإتاوات التي يتحملها شخص مقيم في مصر ، أو التي تتحملها منشأة دائمة في مصر ولو كان مالكها غير مقيم فيها .
(ك) الدخل من أى نشاط آخر يتم القيام به فى مصر .
(ل) الأرباح الرأسمالية المحققة من التصرف فى الأوراق المالية المقيدة فى بورصة الأوراق المالية المصرية ، وكذلك الأرباح الرأسمالية المحققة من التصرف فى الأوراق المالية للشركات المصرية المقيمة غير المقيدة فى بورصة الأوراق المالية المصرية ، سواء كانت مقيدة أو غير مقيدة فى الخارج .
$b105_2$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 3 AND article_suffix_order = 0;

UPDATE article_versions SET
    body = $b105_2$يشمل الدخل المحقق من مصدر فى مصر فى مصر ما يأتى :
(أ) الدخل من الخدمات التى تؤدى بها فى مصر ، بما فى ذلك المرتبات وما فى حكمها .
