(جـ) الدخل الذى يحصل عليه الرياضى أو الفنان من النشاط الذى يقوم به فى مصر .
(د) الدخل من الأعمال التى يؤديها غير المقيم من خلال منشأة دائمة فى مصر .
(هـ) الدخل من التصرفات فى المنقولات التى تخص منشأة دائمة فى مصر .
(و) الدخل من الاستغلال والتصرف فى العقارات وما فى حكمها الكائنة بمصر وما يلحق بها من عقارات بالتخصيص .
(ز) التوزيعات على أسهم شركة أموال مقيمة فى مصر .
(ح) حصص الأرباح التى تدفعها شركة أشخاص مقيمة فى مصر .
(ط) العائد الذى تدفعه الحكومة أو وحدات الإدارة المحلية أو الأشخاص الاعتبارية العامة أو أى شخص مقيم فى مصر ، والعائد الذى يتم سداده من منشأة دائمة فى مصر ولو كان مالكها غير مقيم فيها .
(ى) مبالغ الإيجار ورسوم الترخيص والإتاوات التي يتحملها شخص مقيم في مصر ، أو التي تتحملها منشأة دائمة في مصر ولو كان مالكها غير مقيم فيها .
(ك) الدخل من أى نشاط آخر يتم القيام به فى مصر .
(ل) الأرباح الرأسمالية المحققة من التصرف فى الأوراق المالية المقيدة فى بورصة الأوراق المالية المصرية ، وكذلك الأرباح الرأسمالية المحققة من التصرف فى الأوراق المالية للشركات المصرية المقيمة غير المقيدة فى بورصة الأوراق المالية المصرية ، سواء كانت مقيدة أو غير مقيدة فى الخارج .
$b105_2$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_2$استبدال البندين (ب) و(ى) فقط بموجب القانون 30/2023: تحويل أساس الخضوع من 'يدفعه/تدفع' (من يدفع فعليًا) إلى 'يتحمله/تتحملها' (من يتحمل العبء الاقتصادى)، إغلاقًا لثغرة إعادة الفوترة عبر طرف ثالث.$n105_2$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 3 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 4 (suffix=0) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_3$يقصد بالمنشأة الدائمة فى تطبيق أحكام هذا القانون كل مكان ثابت للأعمال يتم من خلاله تنفيذ كل أو بعض أعمال المشروعات الخاصة بشخص غير مقيم فى مصر ، وتشمل على الأخص :
(أ) محل الإدارة .
(ب) الفرع .
(ج) المكتب .
(د) المصنع .
(ه) ورشة العمل .
(و) المنجم ، أو حقل البترول ، أو بئر الغاز ، أو المحجر ، أو أى مكان آخر لاستخراج الموارد الطبيعية بما فى ذلك الأخشاب أو أى إنتاج آخر من الغابات .
(ز) المزرعة أو الغراس .
(ح) المبانى والمرافق والمخازن المستخدمة كمنافذ للبيع .
(ط) موقع البناء أو الإنشاء ، أو مشروع التركيب أو التجميع ، أو الأنشطة الإشرافية المرتبطة بها ، وذلك فى حال استمرار الموقع أو المشروع أو الأنشطة فى مصر لمدة تزيد فى مجموعها على تسعين يومًا خلال أى فترة اثنا عشر شهرًا .
ويعد فى حكم المنشأة الدائمة ما يلى :
(أ) أى أنشطة يتم تنفيذها فى مصر فيما يتعلق باستكشاف أو استخراج أو استغلال موارد طبيعية ، بما فى ذلك استخدام معدات جوهرية للتركيب أو التجميع ، وذلك فى حال استمرار الموقع أو المشروع أو الأنشطة فى مصر لمدة تزيد فى مجموعها على تسعين يومًا خلال أى فترة اثنا عشر شهرًا .
(ب) تأدية الخدمات ، بما فى ذلك الخدمات الاستشارية التى يقدمها مشروع عن طريق موظفين أو أفراد آخرين ممن يستعين بهم المشروع لهذا الغرض ، وذلك فى حال استمرار تأدية الخدمة لذات المشروع أو لمشروع مرتبط به فى مصر لمدة أو لمدد تزيد فى مجموعها على تسعين يومًا خلال أى فترة اثنا عشر شهرًا .
(ج) مشروع التأمين التابع لإحدى الدول ، فيما عدا ما يتعلق بإعادة التأمين ، وذلك حال قيامه بتحصيل أقساط التأمين فى مصر أو قام بتأمين مخاطر كائنة بها من خلال شخص بخلاف الوكيل ذى الصفة المستقلة .
(د) إذا قام شخص فى مصر نيابة عن مشروع فى دولة أخرى بممارسة عمل أخر فى مصر ، كوكيل مستقل ويعمل للمشروع فى حدود عمله المعتاد ، ومع ذلك إذا كان هذا الشخص يعمل حصريًا أو شبه حصريًا بالنيابة عن مشروع واحد أو أكثر يكون مرتبطًا به ارتباطًا وثيقًا ، فإنه لا يعتبر وكيلاً مستقلاً بمفهوم هذه الفقرة فيما يتعلق بأى مشروع من هذا القبيل .
(هـ) الشخص الذى يعمل لحساب مشروع تابع متى كانت له سلطة إبرام العقود باسم المشروع واعتماد ما لم يقتصر نشاطه على شراء السلع أو البضائع للمشروع ، وكذلك إذا كان هذا الشخص يقوم عادة بدور رئيسى لإبرام العقود يتم إبرامها بشكل متكرر دون تعديل جوهرى من قبل المشروع وكانت هذه العقود :
1- باسم المشروع .
2- لنقل ملكية ، أو لمنح الحق فى استخدام الممتلكات التى يملكها المشروع أو التى له حق استخدامها .
3- لتوفير الخدمات التى يقدمها المشروع .
(و) المشروعات أو الأنشطة التى تتجاوز مدتها تسعين يومًا ، إذا :
1- مارس مشروع لشركة غير مقيمة أنشطة مقيمة فى مصر فى شكل ما يشكل موقع بناء ، أو إنشاء ، أو تركيب ، أو مشروع آخر معين مذكور فى الفقرة الأولى من هذه المادة ، أو ينفذ أنشطة إشرافية أو استشارية ذات علاقة بهذا المكان .
2- تم تنفيذ الأنشطة المتصلة بنفس موقع البناء ، أو الإنشاء ، أو التركيب ، أو أى مكان آخر مذكور فى الفقرة الأولى من هذه المادة من قبل مشروع آخر مرتبط ارتباطًا وثيقًا بالمشروع المذكور ، أثناء فترات زمنية مختلفة ، بواسطة مشروع أو أكثر من المشروعات المرتبطة ارتباطًا وثيقًا بالمشروع .
وتضاف تلك الفترات الزمنية المختلفة للفترة الزمنية الكلية التى يقوم المذكور أولاً بممارسة أنشطته فى موقع البناء أو مشروع الإنشاء ، أو التركيب ، أو أى مكان آخر مشار إليه فى الفقرة الأولى من هذه المادة .
$b105_3$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 4 AND article_suffix_order = 0;

