أكثر من 30000 جنيه إلى 45000 جنيه (10%) .
أكثر من 45000 جنيه إلى 60000 جنيه (15%) .
أكثر من 60000 جنيه إلى 200000 جنيه (20%) .
أكثر من 200000 جنيه إلى 400000 جنيه (22.5%) .
ما زاد على 400000 جنيه (25%) .
