من 1 جنيه إلى 60000 جنيه (20%) .
أكثر من 60000 جنيه إلى 200000 جنيه (20%) .
أكثر من 200000 جنيه إلى 400000 جنيه (22.5%) .
ما زاد على 400000 جنيه (25%) .
خامسًا - صافى الدخل الذى تجاوز 900000 جنيه ولم يتجاوز مليون ومائتى ألف جنيه (1200000 جنيه) :
