-- مادة 13 (suffix=0) - UPDATE (effective_from=2023-07-01)
UPDATE articles SET body = $b105_5$مع عدم الإخلال بالإعفاءات الضريبية الأخرى المقررة بقوانين خاصة يعفى من الضريبة :
1 - مبلغ 15000 جنيه إعفاءً شخصيًا سنويًا للممول .
2 - اشتراكات التأمين الاجتماعى وغيرها مما يستقطع وفقًا لأحكام قوانين التأمين الاجتماعى أو أية نظم بديلة عنها .
3 - اشتراكات العاملين فى صناديق التأمين الخاصة التى تنشأ طبقًا لأحكام قانون صناديق التأمين الخاصة الصادر بالقانون رقم 54 لسنة 1975 .
4 - أقساط التأمين على الحياة والتأمين الصحى على المول لمصلحته أو مصلحة الزوج أو أولاده القصر ، وأية أقساط تأمين لاستحقاق معاش .
5 - المزايا العينية الجماعية التالية :
(أ) الوجبة الغذائية التى تصرف للعاملين .
(ب) النقل الجماعى للعاملين أو ما يقابله من تكلفة .
(جـ) الرعاية الصحية .
(د) الأدوات والملابس اللازمة لأداء العمل .
(هـ) المسكن الذى يتيحه رب العمل للعاملين بمناسبة أدائهم للعمل .
6 - حصة العاملين من الأرباح التى يتقرر توزيعها طبقًا للقانون .
7 - ما يحصل عليه أعضاء السلكين الدبلوماسى والقنصلى والمنظمات الدولية وغيرهم من الممثلين الدبلوماسيين الأجانب وذلك فى نطاق عملهم الرسمى بشرط المعاملة بالمثل وفى حدود تلك المعاملة .
ويشترط لتطبيق الإعفاء المنصوص عليه فى البندين (3) ، (4) ألا تزيد جملة ما يعفى للممول على (15%) من صافى الإيراد أو عشرة آلاف جنيه أيهما أقل ، ولا يجوز تكرار إعفاء الاشتراكات والأقساط المنصوص عليها فى هذين البندين ضمن أى دخل آخر منصوص عليه فى المادة (6) من هذا القانون .
$b105_5$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 13 AND article_suffix_order = 0;

UPDATE article_versions SET
    body = $b105_5$مع عدم الإخلال بالإعفاءات الضريبية الأخرى المقررة بقوانين خاصة يعفى من الضريبة :
1 - مبلغ 15000 جنيه إعفاءً شخصيًا سنويًا للممول .
2 - اشتراكات التأمين الاجتماعى وغيرها مما يستقطع وفقًا لأحكام قوانين التأمين الاجتماعى أو أية نظم بديلة عنها .
3 - اشتراكات العاملين فى صناديق التأمين الخاصة التى تنشأ طبقًا لأحكام قانون صناديق التأمين الخاصة الصادر بالقانون رقم 54 لسنة 1975 .
4 - أقساط التأمين على الحياة والتأمين الصحى على المول لمصلحته أو مصلحة الزوج أو أولاده القصر ، وأية أقساط تأمين لاستحقاق معاش .
5 - المزايا العينية الجماعية التالية :
(أ) الوجبة الغذائية التى تصرف للعاملين .
(ب) النقل الجماعى للعاملين أو ما يقابله من تكلفة .
(جـ) الرعاية الصحية .
(د) الأدوات والملابس اللازمة لأداء العمل .
(هـ) المسكن الذى يتيحه رب العمل للعاملين بمناسبة أدائهم للعمل .
6 - حصة العاملين من الأرباح التى يتقرر توزيعها طبقًا للقانون .
7 - ما يحصل عليه أعضاء السلكين الدبلوماسى والقنصلى والمنظمات الدولية وغيرهم من الممثلين الدبلوماسيين الأجانب وذلك فى نطاق عملهم الرسمى بشرط المعاملة بالمثل وفى حدود تلك المعاملة .
ويشترط لتطبيق الإعفاء المنصوص عليه فى البندين (3) ، (4) ألا تزيد جملة ما يعفى للممول على (15%) من صافى الإيراد أو عشرة آلاف جنيه أيهما أقل ، ولا يجوز تكرار إعفاء الاشتراكات والأقساط المنصوص عليها فى هذين البندين ضمن أى دخل آخر منصوص عليه فى المادة (6) من هذا القانون .
$b105_5$,
    effective_from = '2023-07-01'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_5$استبدال البند (1) فقط بموجب القانون 30/2023: رفع الإعفاء الشخصى السنوى من 9000 جنيه (كما حدده 26/2020) إلى 15000 جنيه. نفاذ: أول الشهر التالى لتاريخ العمل بالقانون (2023-07-01).$n105_5$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 13 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 22 (suffix=0) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_6$يتحدد صافى الأرباح التجارية والصناعية الخاضع للضريبة على أساس إجمالى الربح بعد خصم جميع التكاليف والمصروفات اللازمة لتحقيق هذه الأرباح ، ويشترط فى التكاليف والمصروفات واجبة الخصم ما يأتى :
1 - أن تكون مرتبطة بالنشاط التجارى أو الصناعى للمنشأة ولازمة لمزاولة هذا النشاط .
2 - أن تكون حقيقية ومؤيدة بفواتير وإيصالات إلكترونية اعتبارًا من يوليو 2023 بالنسبة للفواتير الإلكترونية ويناير 2025 بالنسبة للإيصالات الإلكترونية ويجوز للوزير مد المهلتين لفترة لا تزيد على سنة وفقًا لما تحدده اللائحة التنفيذية لهذا القانون ، وذلك فيما عدا التكاليف والمصروفات التى لم يجر العرف على إثباتها بمستندات ، ويجوز للوزير استثناء بعض التكاليف والمصروفات من استلزام إثباتها بفاتورة إلكترونية أو الإيصال الإلكترونى .
$b105_6$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 22 AND article_suffix_order = 0;

UPDATE article_versions SET
