1 - أن تكون مرتبطة بالنشاط التجارى أو الصناعى للمنشأة ولازمة لمزاولة هذا النشاط .
2 - أن تكون حقيقية ومؤيدة بفواتير وإيصالات إلكترونية اعتبارًا من يوليو 2023 بالنسبة للفواتير الإلكترونية ويناير 2025 بالنسبة للإيصالات الإلكترونية ويجوز للوزير مد المهلتين لفترة لا تزيد على سنة وفقًا لما تحدده اللائحة التنفيذية لهذا القانون ، وذلك فيما عدا التكاليف والمصروفات التى لم يجر العرف على إثباتها بمستندات ، ويجوز للوزير استثناء بعض التكاليف والمصروفات من استلزام إثباتها بفاتورة إلكترونية أو الإيصال الإلكترونى .
$b105_6$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_6$استبدال البند (2) فقط بموجب القانون 30/2023: إلزام بإثبات التكاليف والمصروفات واجبة الخصم بفواتير وإيصالات إلكترونية (نفاذ متدرج: يوليو 2023 للفواتير، يناير 2025 للإيصالات، قابل للمد سنة بقرار وزارى).$n105_6$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 22 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 33 (suffix=0) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_7$تحدد الإيرادات الداخلة فى وعاء الضريبة سنويًا على أساس صافى الإيرادات خلال السنة السابقة ، ويشمل الإيراد من المهن غير التجارية عائدات التصرف فى أية أصول مهنية ، وعائدات نقل الخبرات أو التنازل عن مكاتب مزاولة المهنة كليًا أو جزئيًا وأية مبالغ محصلة نتيجة لإغلاق المكتب .
ويكون تحديد صافى الإيسرادات على أساس الإيراد الناتج عن العمليات المختلفة طبقًا لأحكام هذا القانون بعد خصم جميع التكاليف والمصروفات اللازمة لمباشرة المهنة بما فيها إهلاكات الأصول وذلك كله وفق أصول محاسبية مبسطة يصدر بها قرار من الوزير .
ويعد من التكاليف واجبة الخصم ما يلى :
1 - رسوم القيد والاشتراكات السنوية ورسوم مزاولة المهنة .
2 - الضرائب التى يؤديها الممول بمناسبة مباشرة المهنة عدا الضريبة التى يؤديها وفقًا لأحكام هذا القانون .
3 - المبالغ التى يؤديها الممول إلى نقابته وفقًا لنظامها الخاص بالمعاشات .
4 - أقساط التأمين على الحياة والتأمين الصحى على الممول لمصلحته ومصلحة زوجه وأولاده القصر .
وفي تطبيق أحكام البندين (3 و4) من هذه المادة يشترط ألا تزيد جملة ما يعفى للممول على نسبة (15%) من صافي الإيراد الخاضع للضريبة ، أو مبلغ (10,000) جنيه ، أيهما أقل .
ولا يجوز تكرار الخصم ذات الخصم من أى دخل آخر منصوص عليه فى المادة 6 من هذا القانون .
$b105_7$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 33 AND article_suffix_order = 0;

UPDATE article_versions SET
    body = $b105_7$تحدد الإيرادات الداخلة فى وعاء الضريبة سنويًا على أساس صافى الإيرادات خلال السنة السابقة ، ويشمل الإيراد من المهن غير التجارية عائدات التصرف فى أية أصول مهنية ، وعائدات نقل الخبرات أو التنازل عن مكاتب مزاولة المهنة كليًا أو جزئيًا وأية مبالغ محصلة نتيجة لإغلاق المكتب .
