ولا يجوز تكرار الخصم ذات الخصم من أى دخل آخر منصوص عليه فى المادة 6 من هذا القانون .
$b105_7$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_7$استبدال الفقرة الرابعة فقط بموجب القانون 30/2023: رفع سقف إعفاء تكاليف المهن غير التجارية (البندين 3، 4) من نسبة ثابتة (3000 جنيه سنويًا) إلى الأقل من (15% من صافى الإيراد الخاضع للضريبة) أو (10000 جنيه).$n105_7$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 33 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 46 (suffix=1) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_8$تسرى الضريبة على الأرباح الناتجة عن توزيعات الأرباح عن الأسهم والحصص التي يحصل عليها الشخص الطبيعي المقيم في مصر من شركات الأموال أو شركات الأشخاص ، بما في ذلك الشركات المقامة بنظام المناطق الاقتصادية ذات الطبيعة الخاصة ، عدا التوزيعات التي تتم في صورة أسهم مجانية سواء تحققت هذه التوزيعات في مصر أو في الخارج وأيًا كانت الصورة التي يتم بها التوزيع .
وفي تطبيق حكم هذه المادة تعامل الشركات المدنية معاملة شركات الأشخاص .
كما تسري الضريبة على أرباح ، وعوائد وتوزيعات الاستثمار التي يحصل عليها حملة الوثائق في صناديق الاستثمار في أدوات الدين ، وصناديق وشركات رأس المال المخاطر ، وصناديق الاستثمار في الأسهم ، وصناديق الاستثمار العقاري ، والصناديق القابضة المنشأة وفقًا لقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 .
$b105_8$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 1;

