وفي تطبيق حكم هذه المادة تعامل الشركات المدنية معاملة شركات الأشخاص .
كما تسري الضريبة على أرباح ، وعوائد وتوزيعات الاستثمار التي يحصل عليها حملة الوثائق في صناديق الاستثمار في أدوات الدين ، وصناديق وشركات رأس المال المخاطر ، وصناديق الاستثمار في الأسهم ، وصناديق الاستثمار العقاري ، والصناديق القابضة المنشأة وفقًا لقانون سوق رأس المال الصادر بالقانون رقم 95 لسنة 1992 .
$b105_8$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_8$استبدال كامل لمادة (46 مكررًا) بموجب القانون 30/2023: توسيع نطاق الخضوع ليشمل أرباح وعوائد وتوزيعات الاستثمار لحملة الوثائق فى صناديق الاستثمار المختلفة (أدوات دين، رأس مال مخاطر، أسهم، عقارى، قابضة)، وإضافة حكم معاملة الشركات المدنية معاملة شركات الأشخاص.$n105_8$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 1
) AND version_no = 1;

-- مادة 46 (suffix=3) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_9$استثناء من حكم المادة (8) من هذا القانون ، يكون سعر الضريبة على توزيعات الأرباح المنصوص عليها في المادة (46 مكررًا) من هذا القانون المحققة من مصدر في مصر التي يحصل عليها شخص طبيعي مقيم خلال السنة (10%) وذلك دون خصم أية تكاليف ، ويخفض هذا السعر إلى (5%) إذا كانت الأوراق المالية مقيدة في بورصة الأوراق المالية المصرية ، ويكون سعر الضريبة على أرباح وتوزيعات الاستثمار التي يحصل عليها حملة الوثائق في صناديق الاستثمار في أدوات الدين ، وصناديق وشركات رأس المال المخاطر ، وصناديق الاستثمار في الأسهم ، وصناديق الاستثمار العقاري والصناديق القابضة المنشأة وفقًا لقانون سوق رأس المال المشار إليه (15%) بالنسبة إلى الأشخاص الاعتبارية ، و(5%) بالنسبة إلى الأشخاص الطبيعيين .
وعلى الجهات التى تنفذ هذه المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة فى موعد أقصاه خمسة أيام عمل من بداية الشهر التالى للشهر الذى تم فيه التحصيل ، وذلك على النموذج المعد لذلك .
$b105_9$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 3;

UPDATE article_versions SET
