وعلى الجهات التى تنفذ هذه المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة فى موعد أقصاه خمسة أيام عمل من بداية الشهر التالى للشهر الذى تم فيه التحصيل ، وذلك على النموذج المعد لذلك .
$b105_9$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_9$استبدال الفقرة الأولى فقط من مادة (46 مكررًا2) بموجب القانون 30/2023: إضافة أسعار ضريبة مستقلة (15% للأشخاص الاعتبارية، 5% للأشخاص الطبيعيين) على أرباح وتوزيعات الاستثمار لحملة وثائق صناديق الاستثمار، مع بقاء الفقرة الثانية (حجز وتوريد الضريبة) دون تغيير.$n105_9$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 3
) AND version_no = 1;

-- مادة 46 (suffix=4) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_10$تسرى الضريبة على الأرباح الرأسمالية التي تتحقق من التصرف في الأوراق المالية أو الحصص بالشركات ، سواء تحققت هذه الأرباح في مصر أو الحصص بالشركات ، ولا يعد تصرفًا خاضعًا للضريبة عمليات مبادلة الأسهم التي تتم بين شركة مقيدة في بورصة الأوراق المالية المصرية وشركة غير مقيدة فيها بالنسبة للشركات المودعة أسهمها بإحدى شركات الإيداع والقيد المركزي ، وحال التصرف في هذه الأسهم تتخذ تكلفة الاقتناء الفعلية للأسهم قبل المبادلة أساسًا لحساب الأرباح الرأسمالية .
ولا تسرى الضريبة المنصوص عليها فى الفقرة الأولى من هذه المادة على الأرباح الرأسمالية التى يحققها غير المقيم من الأشخاص الطبيعيين أو الاعتباريين من التصرف فى الأوراق المالية المقيدة ببورصة الأوراق المالية المصرية .
كما لا تسرى هذه الضريبة على الأرباح الرأسمالية التى يحققها غير المقيم من التصرف فى أذون الخزانة .
وحال كان المتصرف في الأوراق المالية غير المقيدة والحصص بالشركات غير مقيم فيلتزم بحساب وتوريد الضريبة على الأرباح الرأسمالية المحققة وذلك خلال ستين يومًا من تاريخ المعاملة ، ووفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
$b105_10$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 4;

UPDATE article_versions SET
    body = $b105_10$تسرى الضريبة على الأرباح الرأسمالية التي تتحقق من التصرف في الأوراق المالية أو الحصص بالشركات ، سواء تحققت هذه الأرباح في مصر أو الحصص بالشركات ، ولا يعد تصرفًا خاضعًا للضريبة عمليات مبادلة الأسهم التي تتم بين شركة مقيدة في بورصة الأوراق المالية المصرية وشركة غير مقيدة فيها بالنسبة للشركات المودعة أسهمها بإحدى شركات الإيداع والقيد المركزي ، وحال التصرف في هذه الأسهم تتخذ تكلفة الاقتناء الفعلية للأسهم قبل المبادلة أساسًا لحساب الأرباح الرأسمالية .
ولا تسرى الضريبة المنصوص عليها فى الفقرة الأولى من هذه المادة على الأرباح الرأسمالية التى يحققها غير المقيم من الأشخاص الطبيعيين أو الاعتباريين من التصرف فى الأوراق المالية المقيدة ببورصة الأوراق المالية المصرية .
كما لا تسرى هذه الضريبة على الأرباح الرأسمالية التى يحققها غير المقيم من التصرف فى أذون الخزانة .
وحال كان المتصرف في الأوراق المالية غير المقيدة والحصص بالشركات غير مقيم فيلتزم بحساب وتوريد الضريبة على الأرباح الرأسمالية المحققة وذلك خلال ستين يومًا من تاريخ المعاملة ، ووفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
$b105_10$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_10$عملية مدمجة بموجب القانون 30/2023: استبدال الفقرة الأولى من مادة (46 مكررًا3) [المادة الأولى - استثناء مبادلة الأسهم بين شركات الإيداع المركزى]، مع بقاء الفقرتين الثانية والثالثة كما هما، + إضافة فقرة رابعة جديدة [المادة الثانية - التزام غير المقيم بحساب وتوريد الضريبة خلال 60 يومًا]. دُمجت العمليتان لأنهما تستهدفان نفس صف قاعدة البيانات (46 مكررًا3، suffix=4).$n105_10$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 4
) AND version_no = 1;

-- مادة 46 (suffix=5) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_11$تحدد الأرباح الرأسمالية الخاضعة للضريبة على أساس هذه الأرباح على أساس صافي قيمة هذه الأرباح في محفظة الأوراق المالية المحققة في نهاية السنة الضريبية على أساس الفرق بين سعر بيع أو استبدال أو أي صورة من صور التصرف في الأوراق المالية أو الحصص ، وتكلفة اقتنائها ، وبعد خصم عمولة الوساطة .
وتحدد اللائحة التنفيذية لهذا القانون قواعد حساب تكلفة الاقتناء بالتنسيق مع الهيئة العامة للرقابة المالية وذلك بالنسبة إلى صور التصرف في الأسهم والسندات المتداولة في بورصة الأوراق المالية المصرية ، في ضوء ما يأتي بالنسبة للأسهم المقيدة :
1- تخصم نسبة من الإيراد كتكاليف حكمية ما نظير ما يتحمله الممول مقابل تحقيق الإيراد بما لا يجاوز بالألف (خمسة في الألف) من قيمة العمليات لكل من البيع والشراء .
2- في حالة الطرح الأولي تضاف إلى تكلفة الاقتناء نسبة (25%) من قيمة الأرباح الرأسمالية المحققة ، وذلك بالنسبة إلى طرح الأسهم عند القيد في بورصة الأوراق المالية المصرية .
3- في حالة طرح شرائح أخرى بموجب مذكرة أو معلومات أو تقرير إفصاح معتمدين من الهيئة العامة للرقابة المالية بعد الطرح الأولي تضاف إلى تكلفة الاقتناء نسبة (25%) من قيمة الأرباح الرأسمالية المحققة أيًا كان عدد مرات الطرح .
وتخصم نسبة من الأرباح الرأسمالية للأسهم المقيدة في بورصة الأوراق المالية المصرية التي يحققها الشخص الطبيعي بما يعادل سعر الائتمان والخصم المعلن من البنك المركزي من أول يناير عن فترة الاحتفاظ بالأسهم المتصرف فيها ، وبما لا يجاوز تكلفة الاستثمارات المالية المباشرة مضروبًا في سعر الائتمان والخصم المعلن في أول يناير من سنة البيع ، وألا تزيد التكلفة المعتمدة عن ربحية كل سهم على حدة .
$b105_11$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 5;

