    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_11$استبدال كامل لمادة (46 مكررًا4) بموجب القانون 30/2023: تفصيل دقيق لقواعد حساب تكلفة اقتناء الأوراق المالية المقيدة (تكاليف حكمية 5 بالألف، إضافة 25% عند كل طرح، خصم مرتبط بسعر الائتمان والخصم المعلن من البنك المركزى).$n105_11$
