    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 46 AND a.article_suffix_order = 5
) AND version_no = 1;

-- مادة 46 (suffix=6) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_12$استثناءً من حكم المادة (8) من هذا القانون ، تخضع للضريبة بسعر (10%) الأرباح الرأسمالية المنصوص عليها في المادة (46 مكررًا3) من هذا القانون التي يحصل عليها الأشخاص الطبيعيون المقيمون والأشخاص الاعتبارية من التعامل في الأوراق المالية المقيدة في بورصة الأوراق المالية المصرية ، وذلك دون خصم أية تكاليف .
وفي حال صدور قرار باعتبار القيد في بورصة الأوراق المالية المصرية كأن لم يكن ، تخضع الأرباح الرأسمالية المحققة من مبادلة الأسهم من تاريخ بدء السريان للفقرة الأولى من المادة (46 مكررًا3) من هذا القانون أو من تصرف المساهم في الأسهم المكتتب فيها عند زيادة رأسمال الشركة بالسعر المقرر في المادة (8) أو المادة (49) من هذا القانون ، بحسب الأحوال ، وذلك مع عدم الإخلال بأحكام المادة (92 مكررًا) من هذا القانون .
وعلى الجهات التي تقوم بتسوية المعاملة حساب الضريبة المستحقة طبقًا لهذه المادة ، وتحصيلها ، وتوريدها إلى المصلحة ، طبقًا للنموذج المعد لذلك ، وبالإجراءات وفي المواعيد التي تحددها اللائحة التنفيذية لهذا القانون ، وإذا تعذر على الجهة التي تقوم بالتسوية تحصيل الضريبة فعليها إبلاغ المصلحة بذلك لإعمال شئونها في هذا الشأن ، وذلك دون الإخلال بحق المصلحة في الرجوع على صاحب الشأن حال عدم الالتزام وفقًا لأحكام هذا القانون .
$b105_12$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 46 AND article_suffix_order = 6;

UPDATE article_versions SET
    body = $b105_12$استثناءً من حكم المادة (8) من هذا القانون ، تخضع للضريبة بسعر (10%) الأرباح الرأسمالية المنصوص عليها في المادة (46 مكررًا3) من هذا القانون التي يحصل عليها الأشخاص الطبيعيون المقيمون والأشخاص الاعتبارية من التعامل في الأوراق المالية المقيدة في بورصة الأوراق المالية المصرية ، وذلك دون خصم أية تكاليف .
