    body = $b105_14$لا يعد من التكاليف واجبة الخصم ما يأتى :
1 - العوائد المدينة التي تدفعها الأشخاص الاعتبارية المنصوص عليها في المادة (47) من هذا القانون على القروض والسلفيات التي حصلت عليها فيما يزيد على مثلي متوسط حقوق الملكية وفقًا للقوائم المالية التي يتم إعدادها طبقًا لمعايير المحاسبة المصرية ، ولا تسري أحكام هذا البند على البنوك وشركات التأمين ، وكذلك الشركات التي تباشر نشاط التمويل التي يصدر بتحديدها قرار من الوزير .
2 - المبالغ التى تجنب لتكوين أو تغذية المخصصات على اختلاف أنواعها ، عدا ما يأتى :
(أ) 80% من مخصصات القروض التى تلتزم البنوك بتكوينها وفقًا لقواعد إعداد وتصوير القوائم المالية وأسس التقييم الصادرة عن البنك المركزى .
(ب) المخصصات الفنية التى تلتزم شركات التأمين بتكوينها بالتطبيق لأحكام قانون الإشراف والرقابة على التأمين فى مصر الصادر بالقانون رقم 10 لسنة 1981 .
$b105_14$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_14$استبدال البند (1) فقط بموجب القانون 30/2023: تخفيض نسبة الدين إلى حقوق الملكية فى قاعدة خصم العوائد المدينة من 'أربعة أمثال' (4:1) إلى 'مثلى' (2:1) متوسط حقوق الملكية - تشديد جوهرى لقاعدة الرسملة الضعيفة، مُخفَّف تدريجيًا بحكم مستقل (المادة الخامسة، غير مبنى هنا) يمتد حتى السنة الضريبية 2028 (4:1 لسنة 2023، 3:1 لسنوات 2024-2027، 2:1 لسنة 2028).$n105_14$
WHERE article_id = (
