    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 52 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 56 (suffix=0) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_15$تخضع للضريبة بسعر 20% المبالغ التى يدفعها أصحاب المنشآت الفردية والأشخاص الاعتبارية المقيمة فى مصر والجهات غير المقيمة التى لها منشأة دائمة فى مصر لغير المقيمين فى مصر وذلك دون خصم أية تكاليف منها .
وتشمل هذه المبالغ ما يأتى :
1 - العوائد .
2 - الإتاوات .
3 - مقابل الخدمات ، ولا يعتبر من قبيل مقابل الخدمات نصيب المنشأة الدائمة العاملة فى مصر من المصروفات الإدارية ومصروفات الرقابة والإشراف التى يتحملها مركزها الرئيسى فى الخارج ، ويجب عند تحديد أرباح المنشأة الدائمة ألا يزيد ما يعتمد ضمن المصروفات الإدارية ومصروفات الرقابة والإشراف التى يتحملها المركز الرئيسى فى الخارج على 10% من صافى الربح الضريبى للمنشأة وعلى ألا تتضمن المصروفات المحملة فى حدود هذه النسبة أية أتاوات أو عمولات أو أجور مباشرة وبشرط تقديم شهادة من مراقب حسابات المركز الرئيسى معتمدة وموثقة .
4 - مقابل نشاط رياضى أو الفنان سواء دفع له مباشرة أو من خلال أى جهة .
وتعفى من الضريبة المنصوص عليها في هذه المادة عوائد القروض والتسهيلات الائتمانية التي تحصل عليها الحكومة ووحدات الإدارة المحلية وغيرها من الأشخاص الاعتبارية العامة من مصادر خارج مصر .
وتلتزم المنشآت والأشخاص والجهات المشار إليها فى الفقرة الأولى من هذه المادة بما فى ذلك الشركات والمنشآت والفروع المقامة وفقًا لأحكام قانون المناطق الاقتصادية ذات الطبيعة الخاصة وكذلك المشروعات المقامة بنظام المناطق الحرة بحجز مقدار الضريبة المستحقة وتوريدها إلى المصلحة فى أول يوم عمل تال لليوم الذى تم فيه حجز الضريبة .
$b105_15$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 56 AND article_suffix_order = 0;

UPDATE article_versions SET
    body = $b105_15$تخضع للضريبة بسعر 20% المبالغ التى يدفعها أصحاب المنشآت الفردية والأشخاص الاعتبارية المقيمة فى مصر والجهات غير المقيمة التى لها منشأة دائمة فى مصر لغير المقيمين فى مصر وذلك دون خصم أية تكاليف منها .
وتشمل هذه المبالغ ما يأتى :
1 - العوائد .
2 - الإتاوات .
3 - مقابل الخدمات ، ولا يعتبر من قبيل مقابل الخدمات نصيب المنشأة الدائمة العاملة فى مصر من المصروفات الإدارية ومصروفات الرقابة والإشراف التى يتحملها مركزها الرئيسى فى الخارج ، ويجب عند تحديد أرباح المنشأة الدائمة ألا يزيد ما يعتمد ضمن المصروفات الإدارية ومصروفات الرقابة والإشراف التى يتحملها المركز الرئيسى فى الخارج على 10% من صافى الربح الضريبى للمنشأة وعلى ألا تتضمن المصروفات المحملة فى حدود هذه النسبة أية أتاوات أو عمولات أو أجور مباشرة وبشرط تقديم شهادة من مراقب حسابات المركز الرئيسى معتمدة وموثقة .
4 - مقابل نشاط رياضى أو الفنان سواء دفع له مباشرة أو من خلال أى جهة .
وتعفى من الضريبة المنصوص عليها في هذه المادة عوائد القروض والتسهيلات الائتمانية التي تحصل عليها الحكومة ووحدات الإدارة المحلية وغيرها من الأشخاص الاعتبارية العامة من مصادر خارج مصر .
وتلتزم المنشآت والأشخاص والجهات المشار إليها فى الفقرة الأولى من هذه المادة بما فى ذلك الشركات والمنشآت والفروع المقامة وفقًا لأحكام قانون المناطق الاقتصادية ذات الطبيعة الخاصة وكذلك المشروعات المقامة بنظام المناطق الحرة بحجز مقدار الضريبة المستحقة وتوريدها إلى المصلحة فى أول يوم عمل تال لليوم الذى تم فيه حجز الضريبة .
$b105_15$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_15$استبدال الفقرة الثالثة فقط بموجب القانون 30/2023: إسقاط إعفاء عوائد قروض/تسهيلات شركات القطاعين العام والخاص (كان بشرط مدة 3 سنوات على الأقل)، تاركًا الإعفاء مقصورًا على الحكومة ووحدات الإدارة المحلية والأشخاص الاعتبارية العامة فقط. الإعفاء القديم يبقى ساريًا على القروض القائمة فعلاً قبل نفاذ هذا القانون بحكم مستقل (المادة السادسة، غير مبنى هنا).$n105_15$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 56 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 56 (suffix=1) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_16$تخضع للضريبة بسعر (10%) دون خصم أية تكاليف توزيعات الأرباح التي تجريها شركات الأموال أو شركات الأشخاص ، بما في ذلك الشركات المقامة بنظام المناطق الاقتصادية ذات الطبيعة الخاصة للشخص الطبيعي غير المقيم والشخص الاعتباري المقيم أو غير المقيم بما في ذلك أرباح الأشخاص الاعتبارية غير المقيمة التي تحققها من خلال منشأة دائمة من خلال منشأة دائمة في مصر ، عدا التوزيعات التي تتم في صورة أسهم مجانية ، ويكون سعر هذه الضريبة (5%) من توزيعات الأرباح إذا كانت الأوراق المالية مقيدة في بورصة الأوراق المالية المصرية دون خصم أي تكاليف .
وفي تطبيق حكم هذه المادة تعامل الشركات المدنية معاملة شركات الأشخاص .
وتعد أرباح الأشخاص الاعتبارية غير المقيمة التي تحققها من خلال منشأة دائمة في مصر موزعة حكمًا خلال ستين يومًا من تاريخ ختام السنة المالية للمنشأة الدائمة .
وتستبعد توزيعات الأرباح التي تحصل عليها الأشخاص الاعتبارية المقيمة من أشخاص اعتبارية مقيمة أخرى وما يقابلها من تكلفة ووعاء الضريبة على أرباح الأشخاص الاعتبارية المنصوص عليها في هذا القانون من الكتاب الثالث من هذا القانون ، وفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
وتخصم من الضريبة المستحقة على التوزيعات المدفوعة لشركة مقيمة مقابل الضريبة المسددة التي حصلت عليها الشركة الموزعة من شركة مقيمة أخرى ، وذلك بالشروط الآتية :
1 - أن يكون الخصم في حدود قيمة التوزيعات منسوبة إلى إجمالي الإيرادات التي حققتها الشركة الموزعة .
2 - إذا زادت نسبة المساهمة في الشركة القائمة بالتوزيع على (25%) من رأسمال الشركة المقيمة أو حقوق التصويت .
3 - ألا تقل مدة حيازة الشركة للأسهم أو الحصص عن سنتين من تاريخ اقتناء الأسهم للشركات المودعة أسهمها وحصصها بإحدى شركات الإيداع والقيد المركزي .
4 - ألا تتجاوز الضريبة المخصومة الضريبة التي يتم استقطاعها على ذات التوزيعات المدفوعة التي يحدد هذا القانون لهذا الخصم طريقة حسابها .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وضوابط الخصم ، وعلى الجهات التي تنفذ المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة في موعد أقصاه خمسة أيام عمل من بداية الشهر التالي للشهر الذي تم فيه التحصيل ، وذلك على النموذج المعد لذلك .
$b105_16$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 56 AND article_suffix_order = 1;

