$b105_16$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_16$استبدال كامل لمادة (56 مكررًا) بموجب القانون 30/2023: تفصيل واسع لآلية خصم الضريبة على أرباح الأشخاص الاعتبارية غير المقيمة من خلال منشأة دائمة (اعتبار الأرباح موزعة حكمًا خلال 60 يومًا من ختام السنة المالية)، واستحداث آلية خصم ضريبى (tax credit) للتوزيعات المتعاقبة بين شركات مقيمة بشروط حيازة وملكية محددة.$n105_16$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 56 AND a.article_suffix_order = 1
) AND version_no = 1;

-- مادة 139 (suffix=0) - UPDATE (effective_from=2023-06-16)
UPDATE articles SET body = $b105_17$ينشأ مجلس أعلى للضرائب برئاسة رئيس مجلس الوزراء ، يكون مقره مدينة القاهرة ، ويهدف إلى ضمان حقوق دافعي الضرائب على اختلاف أنواعها ومعاونتهم على الوفاء بالتزاماتهم القانونية التي تفرضها عليهم القوانين الضريبية وغيرها من القوانين ذات الصلة .
ويختص المجلس بالآتي :
1- دراسة وإقرار وثيقة حقوق دافعي الضرائب .
2- إبداء الرأي في مشروعات القوانين الضريبية ، وكذلك مشروعات لوائحها التنفيذية .
3- إعداد الدراسات وتقديم الاقتراحات التي تساعد على تحسين أداء المصالح الضريبية ، ويجوز لوزارة المالية أن تعرض على المجلس أيًا من المسائل الضريبية لمناقشتها .
4- تلقي شكاوى وتظلمات دافعي الضرائب وغيرهم من ذوى الشأن وبحثها مع المصالح الضريبية المختصة ، والعمل على حلها ، وإعداد تقرير بشأنها يرفع إلى مجلس الوزراء .
5- توفير المساعدة القانونية والفنية لدافعي الضرائب وغيرهم من ذوى الشأن غير القادرين ، من خلال الاستعانة بالمحاسبين والمحامين للدفاع عن مصالحهم أمام اللجان والمحاكم المختصة .
6- معاونة المصالح الضريبية في إعداد أدلة العمل الضريبي التي تساعد على تبصير دافعي الضرائب وغيرهم من ذوى الشأن بحقوقهم والتزاماتهم الضريبية .
7- اقتراح الآليات الكفيلة لمعالجة ظاهرة المتأخرات الضريبية في جميع أنواع الضرائب والجمارك .
8- التنسيق مع المجلس الأعلى للاستثمار ووزارة المالية لتعزيز استخدامات الضريبة كمحفز للنشاط الاقتصادي ، وضبط العلاقة بين المستثمرين والدولة في ضوء ما يتم من مراجعة للتشريعات والإجراءات والحوافز الضريبية والجمركية ، وقياس حالات الامتثال الضريبي للمستثمرين .
9- القياس المستمر لمشروعات الإدارة الضريبية ومدى اعتمادها على الأساس الفعلي في تحصيل جميع أنواع الضرائب والجمارك ، وإجراءاتها لخفض الطعون والمنازعات الضريبية إلى أقل حد ممكن .
ويصدر بتشكيل المجلس ، وتحديد أية اختصاصات أخرى له ، ونظام العمل به ، قرار من رئيس الجمهورية .
$b105_17$, updated_at = now()
WHERE law_id = (SELECT id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law')
  AND article_no = 139 AND article_suffix_order = 0;

