$b105_17$,
    effective_from = '2023-06-16'::date,
    status = 'active',
    effective_to = NULL,
    amended_by_law_no = 30,
    amended_by_law_year = 2023,
    change_note = $n105_17$استبدال كامل بموجب القانون 30/2023 (المادة الأولى): المادة كانت موجودة بالفعل فى قاعدة البيانات بنص موجز جدًا (مجرد إنشاء مجلس أعلى للضرائب دون تفصيل)؛ استُبدلت بنص تفصيلى كامل (9 اختصاصات محددة) لهذا المجلس.$n105_17$
WHERE article_id = (
    SELECT a.id FROM articles a JOIN laws l ON l.id = a.law_id
    WHERE l.law_no = 91 AND l.law_year = 2005 AND l.kind = 'law'
      AND a.article_no = 139 AND a.article_suffix_order = 0
) AND version_no = 1;

-- مادة 4 (suffix=1) - INSERT/UPSERT جديدة (effective_from=2023-06-16)
WITH ins105_18 AS (
    INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
    SELECT id, 4, 1, $h105_18$قانون 91/2005 > الكتاب الأول > مادة 4 مكررًا [أُضيفت بالمادة الثانية من القانون 30/2023]$h105_18$, $b105_18$استثناء من أحكام المادة (4) من هذا القانون ، لا تعد منشأة دائمة كل ما يأتي :
(أ) الانتفاع بالتسهيلات فقط بغرض تخزين أو عرض السلع أو البضائع المملوكة للمشروع .
(ب) الاحتفاظ بمخزون من السلع أو البضائع المملوكة للمشروع فقط بغرض التخزين أو العرض .
(ج) الاحتفاظ بمخزون من السلع أو البضائع المملوكة للمشروع فقط بغرض تشغيلها بواسطة مشروع آخر .
(د) استعمال مكان ثابت للعمل فقط بغرض شراء سلع أو بضائع أو تجميع معلومات للمشروع .
(ه) استعمال مكان ثابت للعمل فقط بغرض القيام بأي نشاط آخر ذي صفة تمهيدية أو مساعدة للمشروع .
(و) استعمال مكان ثابت للعمل فقط للجمع بين أي من الأنشطة المنصوص عليها في البنود (أ ، ب ، ج ، د ، ه) من هذه المادة ، بشرط أن يكون النشاط الكلي للمكان الثابت الناتج عن مجموع هذه الأنشطة ذا صفة تمهيدية أو مساعدة .
(ز) شركة مقيمة في دولة أخرى تحت سيطرة شركة مقيمة في مصر تزاول نشاطًا في تلك الدولة الأخرى .
كما لا تعد منشأة دائمة الأنشطة المنصوص عليها في هذه المادة إذا تم القيام بها بواسطة الشخص الذي يعمل لحساب مشروع تابع ولا يقوم بأي دور في إبرام العقود .
ولا ينطبق حكم هذه المادة على أي مكان ثابت للعمل يستخدمه أو يحتفظ به مشروع أو مشروع مرتبط ارتباطًا وثيقًا يزاول أنشطة تجارية في نفس المكان أو في مكان آخر داخل مصر :
(أ) يشكل ذلك المكان أو أي مكان آخر منشأة دائمة للمشروع أو للمشروع المرتبط ارتباطًا وثيقًا بموجب أحكام هذه المادة .
(ب) النشاط الإجمالي الناتج عن مجموعة الأنشطة التي يقوم بها المشروعان في نفس المكان ، أو من قبل نفس المشروع أو المشروعات المرتبطة ارتباطًا وثيقًا في المكانين ، ليست ذات طبيعة تمهيدية أو مساعدة ، شريطة أن تشكل الأنشطة التي يقوم بها المشروعان في نفس المكان أو من قبل نفس المشروع أو المشروعات المرتبطة ارتباطًا وثيقًا في المكانين ، وظائف تكميلية تشكل جزءًا من عملية تجارية متماسكة .
ويعد الشخص مرتبطًا ارتباطًا وثيقًا بمشروع بناء على جميع الحقائق والظروف ذات الصلة أو السيطرة على الآخر في حال خضوع كليهما لسيطرة نفس الأشخاص أو المشروعات ، وعلى أية حال يعتبر أي شخص مرتبطًا ارتباطًا وثيقًا بمشروع في حال امتلاك أحدهما بشكل مباشر أو غير مباشر أكثر من (50%) من إجمالي الأسهم أو حقوق التصويت أو حقوق الملكية .
