-- ===== كتلة التحقق =====

DO $verify105$
DECLARE
    v_law_id uuid;
    v_art_body text;
    v_ver_body text;
    v_amended_no int;
    v_amended_year int;
    v_status text;
    v_eff_from date;
    v_eff_to date;
BEGIN
    SELECT id INTO v_law_id FROM laws WHERE law_no = 91 AND law_year = 2005 AND kind = 'law';
    IF v_law_id IS NULL THEN
        RAISE EXCEPTION 'migration 105: سجل قانون 91/2005 غير موجود - يجب تشغيل migration 076 أولاً.';
    END IF;

    SELECT a.body, av.body, av.amended_by_law_no, av.amended_by_law_year, av.status, av.effective_from
    INTO v_art_body, v_ver_body, v_amended_no, v_amended_year, v_status, v_eff_from
    FROM articles a
    JOIN article_versions av ON av.article_id = a.id AND av.version_no = 1
    WHERE a.law_id = v_law_id AND a.article_no = 1 AND a.article_suffix_order = 0;

    IF v_art_body IS NULL THEN
        RAISE EXCEPTION 'migration 105: المادة 1 (suffix=0) غير موجودة.';
    END IF;
    IF v_art_body <> $vb105_1$فى تطبيق أحكام هذا القانون يقصد بالألفاظ والعبارات التالية المعنى المبين أمام كل منها :
- الضريبة : الضريبة على الدخل .
- الوزير : وزير المالية .
- رئيس المصلحة : رئيس مصلحة الضرائب العامة .
- المصلحة : مصلحة الضرائب العامة .
- الممول : الشخص الطبيعى أو الشخص الاعتبارى الخاضع للضريبة وفقًا لأحكام هذا القانون .
- شركات الأموال : شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة .
- شركات الأشخاص : شركات التضامن وشركات التوصية البسيطة .
- شركة الواقع : الشركة التي تقوم أو تستمر بين أشخاص طبيعيين دون استيفاء إجراءات الانعقاد أو الشهر ، ولا تعد شركة واقع المنشأة الفردية التي آلت بالميراث على أن يقدم عنها إقرار واحد مضمنًا حصة كل وارث فيها .
- المشروع : الكيان الاقتصادى الذى يزاول النشاط الأصلى فى مصر أو المنشأة الدائمة فى مصر التابعة لكيان اقتصادى فى الخارج .
- الشخص المرتبط : كل شخص يرتبط بممول بعلاقة تؤثر في تحديد وعاء الضريبة بشكل مباشر أو غير مباشر ، سواء من خلال الإدارة أو السيطرة أو الملكية ، وبوجه عام يكون الشخصان مرتبطين إذا كانت العلاقة بينهما تصل إلى حد إمكانية قيام أحدهما بالتصرف وفقًا لتوجيهات ، أو طلبات ، أو اقتراحات ، أو إرادة الشخص الآخر ، أو شخص ثالث .
ويعامل الأشخاص التالي ذكرهم بوصفهم أشخاصًا مرتبطين :
1- الزوج والزوجة والأصول والفروع .
2- شركة الأشخاص والشركاء المتضامنون والموصون فيها .
3- شركة الأموال والشخص الذي يملك فيها بشكل مباشر أو غير مباشر (50%) على الأقل من حقوق التصويت أو الإدارة في الشركة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال .
4- أي شركتين أو أكثر يملك شخص آخر (50%) أو أكثر على الأقل من حقوق التصويت أو الإدارة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال في الشركتين أو أكثر .
وعند تطبيق البندين 2 أو 3 أو 4 من الفقرة السابقة ، فإن الحيازة التي تنسب إلى شخص ما من قبل شخص مرتبط لا يجوز أن تنسب إلى شخص آخر مرتبط .
لا يعتبر شخصان مرتبطين لمجرد أن أحدهما يعد عاملاً أو عميلاً لدى الشخص الآخر أو أن كليهما يعد عاملاً أو عميلاً لدى شخص ثالث ، ما لم يؤثر هذا الارتباط بشكل مباشر أو غير مباشر فى تحديد وعاء الضريبة .
- السعر المحايد : السعر الذى يتم التعامل بمقتضاه بين شخصين غير مرتبطين أو أكثر ، ويتحدد وفقًا لقوى السوق وظروف التعامل .
- الإتاوات : المبالغ المدفوعة أيًا كان نوعها مقابل استعمال أو الحق أو الحق فى استعمال حقوق النشر الخاصة بعمل أدبى أو فنى أو علمى بما فى ذلك أفلام السينما ، أو براءة اختراع أو علامة تجارية أو تصميم أو نموذج أو خطة أو تركيبة أو عملية سرية أو مقابل استعمال أو الحق فى استعمال معدات صناعية أو تجارية أو علمية أو معلومات متعلقة بالخبرة الصناعية أو التجارية أو العلمية .
- توزيعات الأرباح : أى دخل مستمد من الأسهم أو الحصص ، بما فى ذلك أسهم التمتع أو حقوق التمتع ، وأسهم التعدين ، وأسهم التأسيس ، وأية حقوق أخرى تعطى حق المشاركة فى الأرباح ، سواء كانت هذه التوزيعات نقدية أو أسهم مجانية أو على شكل سندات أو حصص تأسيس أو على أية صورة أخرى .
$vb105_1$ THEN
        RAISE EXCEPTION 'migration 105: نص المادة 1 (articles.body) لا يطابق المتوقع.';
    END IF;
    IF v_ver_body <> $vb105_1$فى تطبيق أحكام هذا القانون يقصد بالألفاظ والعبارات التالية المعنى المبين أمام كل منها :
- الضريبة : الضريبة على الدخل .
- الوزير : وزير المالية .
- رئيس المصلحة : رئيس مصلحة الضرائب العامة .
- المصلحة : مصلحة الضرائب العامة .
- الممول : الشخص الطبيعى أو الشخص الاعتبارى الخاضع للضريبة وفقًا لأحكام هذا القانون .
- شركات الأموال : شركات المساهمة وشركات التوصية بالأسهم والشركات ذات المسئولية المحدودة .
- شركات الأشخاص : شركات التضامن وشركات التوصية البسيطة .
- شركة الواقع : الشركة التي تقوم أو تستمر بين أشخاص طبيعيين دون استيفاء إجراءات الانعقاد أو الشهر ، ولا تعد شركة واقع المنشأة الفردية التي آلت بالميراث على أن يقدم عنها إقرار واحد مضمنًا حصة كل وارث فيها .
- المشروع : الكيان الاقتصادى الذى يزاول النشاط الأصلى فى مصر أو المنشأة الدائمة فى مصر التابعة لكيان اقتصادى فى الخارج .
- الشخص المرتبط : كل شخص يرتبط بممول بعلاقة تؤثر في تحديد وعاء الضريبة بشكل مباشر أو غير مباشر ، سواء من خلال الإدارة أو السيطرة أو الملكية ، وبوجه عام يكون الشخصان مرتبطين إذا كانت العلاقة بينهما تصل إلى حد إمكانية قيام أحدهما بالتصرف وفقًا لتوجيهات ، أو طلبات ، أو اقتراحات ، أو إرادة الشخص الآخر ، أو شخص ثالث .
ويعامل الأشخاص التالي ذكرهم بوصفهم أشخاصًا مرتبطين :
1- الزوج والزوجة والأصول والفروع .
2- شركة الأشخاص والشركاء المتضامنون والموصون فيها .
3- شركة الأموال والشخص الذي يملك فيها بشكل مباشر أو غير مباشر (50%) على الأقل من حقوق التصويت أو الإدارة في الشركة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال .
4- أي شركتين أو أكثر يملك شخص آخر (50%) أو أكثر على الأقل من حقوق التصويت أو الإدارة ، أو من حقوق توزيع الأرباح ، أو من حقوق رأس المال في الشركتين أو أكثر .
وعند تطبيق البندين 2 أو 3 أو 4 من الفقرة السابقة ، فإن الحيازة التي تنسب إلى شخص ما من قبل شخص مرتبط لا يجوز أن تنسب إلى شخص آخر مرتبط .
لا يعتبر شخصان مرتبطين لمجرد أن أحدهما يعد عاملاً أو عميلاً لدى الشخص الآخر أو أن كليهما يعد عاملاً أو عميلاً لدى شخص ثالث ، ما لم يؤثر هذا الارتباط بشكل مباشر أو غير مباشر فى تحديد وعاء الضريبة .
- السعر المحايد : السعر الذى يتم التعامل بمقتضاه بين شخصين غير مرتبطين أو أكثر ، ويتحدد وفقًا لقوى السوق وظروف التعامل .
- الإتاوات : المبالغ المدفوعة أيًا كان نوعها مقابل استعمال أو الحق أو الحق فى استعمال حقوق النشر الخاصة بعمل أدبى أو فنى أو علمى بما فى ذلك أفلام السينما ، أو براءة اختراع أو علامة تجارية أو تصميم أو نموذج أو خطة أو تركيبة أو عملية سرية أو مقابل استعمال أو الحق فى استعمال معدات صناعية أو تجارية أو علمية أو معلومات متعلقة بالخبرة الصناعية أو التجارية أو العلمية .
- توزيعات الأرباح : أى دخل مستمد من الأسهم أو الحصص ، بما فى ذلك أسهم التمتع أو حقوق التمتع ، وأسهم التعدين ، وأسهم التأسيس ، وأية حقوق أخرى تعطى حق المشاركة فى الأرباح ، سواء كانت هذه التوزيعات نقدية أو أسهم مجانية أو على شكل سندات أو حصص تأسيس أو على أية صورة أخرى .
$vb105_1$ THEN
        RAISE EXCEPTION 'migration 105: نص المادة 1 (article_versions.body) لا يطابق المتوقع.';
    END IF;
    IF v_amended_no <> 30 OR v_amended_year <> 2023 THEN
        RAISE EXCEPTION 'migration 105: amended_by_law_no/year للمادة 1 غير مطابق (متوقع 30/2023).';
    END IF;
    IF v_eff_from <> '2023-06-16'::date THEN
        RAISE EXCEPTION 'migration 105: effective_from للمادة 1 غير مطابق (متوقع 2023-06-16، الفعلى %)', v_eff_from;
    END IF;

    SELECT a.body, av.body, av.amended_by_law_no, av.amended_by_law_year, av.status, av.effective_from
    INTO v_art_body, v_ver_body, v_amended_no, v_amended_year, v_status, v_eff_from
    FROM articles a
    JOIN article_versions av ON av.article_id = a.id AND av.version_no = 1
    WHERE a.law_id = v_law_id AND a.article_no = 3 AND a.article_suffix_order = 0;

    IF v_art_body IS NULL THEN
        RAISE EXCEPTION 'migration 105: المادة 3 (suffix=0) غير موجودة.';
    END IF;
    IF v_art_body <> $vb105_2$يشمل الدخل المحقق من مصدر فى مصر فى مصر ما يأتى :
(أ) الدخل من الخدمات التى تؤدى بها فى مصر ، بما فى ذلك المرتبات وما فى حكمها .
(ب) الدخل الذي يتحمله رب عمل مقيم في مصر ، ولو أدى العمل في الخارج .
(جـ) الدخل الذى يحصل عليه الرياضى أو الفنان من النشاط الذى يقوم به فى مصر .
(د) الدخل من الأعمال التى يؤديها غير المقيم من خلال منشأة دائمة فى مصر .
(هـ) الدخل من التصرفات فى المنقولات التى تخص منشأة دائمة فى مصر .
(و) الدخل من الاستغلال والتصرف فى العقارات وما فى حكمها الكائنة بمصر وما يلحق بها من عقارات بالتخصيص .
(ز) التوزيعات على أسهم شركة أموال مقيمة فى مصر .
(ح) حصص الأرباح التى تدفعها شركة أشخاص مقيمة فى مصر .
(ط) العائد الذى تدفعه الحكومة أو وحدات الإدارة المحلية أو الأشخاص الاعتبارية العامة أو أى شخص مقيم فى مصر ، والعائد الذى يتم سداده من منشأة دائمة فى مصر ولو كان مالكها غير مقيم فيها .
(ى) مبالغ الإيجار ورسوم الترخيص والإتاوات التي يتحملها شخص مقيم في مصر ، أو التي تتحملها منشأة دائمة في مصر ولو كان مالكها غير مقيم فيها .
(ك) الدخل من أى نشاط آخر يتم القيام به فى مصر .
(ل) الأرباح الرأسمالية المحققة من التصرف فى الأوراق المالية المقيدة فى بورصة الأوراق المالية المصرية ، وكذلك الأرباح الرأسمالية المحققة من التصرف فى الأوراق المالية للشركات المصرية المقيمة غير المقيدة فى بورصة الأوراق المالية المصرية ، سواء كانت مقيدة أو غير مقيدة فى الخارج .
$vb105_2$ THEN
        RAISE EXCEPTION 'migration 105: نص المادة 3 (articles.body) لا يطابق المتوقع.';
    END IF;
