(هـ) الشخص الذى يعمل لحساب مشروع تابع متى كانت له سلطة إبرام العقود باسم المشروع واعتماد ما لم يقتصر نشاطه على شراء السلع أو البضائع للمشروع ، وكذلك إذا كان هذا الشخص يقوم عادة بدور رئيسى لإبرام العقود يتم إبرامها بشكل متكرر دون تعديل جوهرى من قبل المشروع وكانت هذه العقود :
1- باسم المشروع .
2- لنقل ملكية ، أو لمنح الحق فى استخدام الممتلكات التى يملكها المشروع أو التى له حق استخدامها .
3- لتوفير الخدمات التى يقدمها المشروع .
(و) المشروعات أو الأنشطة التى تتجاوز مدتها تسعين يومًا ، إذا :
1- مارس مشروع لشركة غير مقيمة أنشطة مقيمة فى مصر فى شكل ما يشكل موقع بناء ، أو إنشاء ، أو تركيب ، أو مشروع آخر معين مذكور فى الفقرة الأولى من هذه المادة ، أو ينفذ أنشطة إشرافية أو استشارية ذات علاقة بهذا المكان .
2- تم تنفيذ الأنشطة المتصلة بنفس موقع البناء ، أو الإنشاء ، أو التركيب ، أو أى مكان آخر مذكور فى الفقرة الأولى من هذه المادة من قبل مشروع آخر مرتبط ارتباطًا وثيقًا بالمشروع المذكور ، أثناء فترات زمنية مختلفة ، بواسطة مشروع أو أكثر من المشروعات المرتبطة ارتباطًا وثيقًا بالمشروع .
وتضاف تلك الفترات الزمنية المختلفة للفترة الزمنية الكلية التى يقوم المذكور أولاً بممارسة أنشطته فى موقع البناء أو مشروع الإنشاء ، أو التركيب ، أو أى مكان آخر مشار إليه فى الفقرة الأولى من هذه المادة .
