2- في حالة الطرح الأولي تضاف إلى تكلفة الاقتناء نسبة (25%) من قيمة الأرباح الرأسمالية المحققة ، وذلك بالنسبة إلى طرح الأسهم عند القيد في بورصة الأوراق المالية المصرية .
3- في حالة طرح شرائح أخرى بموجب مذكرة أو معلومات أو تقرير إفصاح معتمدين من الهيئة العامة للرقابة المالية بعد الطرح الأولي تضاف إلى تكلفة الاقتناء نسبة (25%) من قيمة الأرباح الرأسمالية المحققة أيًا كان عدد مرات الطرح .
وتخصم نسبة من الأرباح الرأسمالية للأسهم المقيدة في بورصة الأوراق المالية المصرية التي يحققها الشخص الطبيعي بما يعادل سعر الائتمان والخصم المعلن من البنك المركزي من أول يناير عن فترة الاحتفاظ بالأسهم المتصرف فيها ، وبما لا يجاوز تكلفة الاستثمارات المالية المباشرة مضروبًا في سعر الائتمان والخصم المعلن في أول يناير من سنة البيع ، وألا تزيد التكلفة المعتمدة عن ربحية كل سهم على حدة .
$vb105_11$ THEN
        RAISE EXCEPTION 'migration 105: نص المادة 46 (article_versions.body) لا يطابق المتوقع.';
    END IF;
    IF v_amended_no <> 30 OR v_amended_year <> 2023 THEN
        RAISE EXCEPTION 'migration 105: amended_by_law_no/year للمادة 46 غير مطابق (متوقع 30/2023).';
    END IF;
    IF v_eff_from <> '2023-06-16'::date THEN
        RAISE EXCEPTION 'migration 105: effective_from للمادة 46 غير مطابق (متوقع 2023-06-16، الفعلى %)', v_eff_from;
    END IF;

    SELECT a.body, av.body, av.amended_by_law_no, av.amended_by_law_year, av.status, av.effective_from
    INTO v_art_body, v_ver_body, v_amended_no, v_amended_year, v_status, v_eff_from
    FROM articles a
    JOIN article_versions av ON av.article_id = a.id AND av.version_no = 1
    WHERE a.law_id = v_law_id AND a.article_no = 46 AND a.article_suffix_order = 6;

    IF v_art_body IS NULL THEN
        RAISE EXCEPTION 'migration 105: المادة 46 (suffix=6) غير موجودة.';
    END IF;
    IF v_art_body <> $vb105_12$استثناءً من حكم المادة (8) من هذا القانون ، تخضع للضريبة بسعر (10%) الأرباح الرأسمالية المنصوص عليها في المادة (46 مكررًا3) من هذا القانون التي يحصل عليها الأشخاص الطبيعيون المقيمون والأشخاص الاعتبارية من التعامل في الأوراق المالية المقيدة في بورصة الأوراق المالية المصرية ، وذلك دون خصم أية تكاليف .
وفي حال صدور قرار باعتبار القيد في بورصة الأوراق المالية المصرية كأن لم يكن ، تخضع الأرباح الرأسمالية المحققة من مبادلة الأسهم من تاريخ بدء السريان للفقرة الأولى من المادة (46 مكررًا3) من هذا القانون أو من تصرف المساهم في الأسهم المكتتب فيها عند زيادة رأسمال الشركة بالسعر المقرر في المادة (8) أو المادة (49) من هذا القانون ، بحسب الأحوال ، وذلك مع عدم الإخلال بأحكام المادة (92 مكررًا) من هذا القانون .
وعلى الجهات التي تقوم بتسوية المعاملة حساب الضريبة المستحقة طبقًا لهذه المادة ، وتحصيلها ، وتوريدها إلى المصلحة ، طبقًا للنموذج المعد لذلك ، وبالإجراءات وفي المواعيد التي تحددها اللائحة التنفيذية لهذا القانون ، وإذا تعذر على الجهة التي تقوم بالتسوية تحصيل الضريبة فعليها إبلاغ المصلحة بذلك لإعمال شئونها في هذا الشأن ، وذلك دون الإخلال بحق المصلحة في الرجوع على صاحب الشأن حال عدم الالتزام وفقًا لأحكام هذا القانون .
