    SELECT a.body, av.body, av.amended_by_law_no, av.amended_by_law_year, av.status, av.effective_from
    INTO v_art_body, v_ver_body, v_amended_no, v_amended_year, v_status, v_eff_from
    FROM articles a
    JOIN article_versions av ON av.article_id = a.id AND av.version_no = 1
    WHERE a.law_id = v_law_id AND a.article_no = 50 AND a.article_suffix_order = 0;

    IF v_art_body IS NULL THEN
        RAISE EXCEPTION 'migration 105: المادة 50 (suffix=0) غير موجودة.';
    END IF;
    IF v_art_body <> $vb105_13$يعفى من الضريبة :
1 - الوزارات والمصالح الحكومية .
2 - ملغاة .
3 - الجمعيات والمؤسسات الأهلية المنشأة طبقًا لأحكام القانون المنظم للعمل الأهلي ، وذلك في حدود الغرض الذي تأسست من أجله .
4 - الجهات التي لا تهدف إلى الربح وتباشر أنشطة ذات طبيعة اجتماعية ، أو علمية أو رياضية أو ثقافية ، وذلك في حدود ما تقوم به من نشاط ليست له صفة تجارية أو صناعية أو مهنية .
5 - أرباح صناديق التأمين الخاصة الخاضعة لأحكام قانون صناديق التأمين الخاصة الصادر بالقانون رقم 54 لسنة 1975 .
6 - المنظمات الدولية وهيئات التعاون الفني وممثلوها والتي تنص اتفاقية دولية على إعفائها .
7 - عوائد السندات غير الحكومية المقيدة في جداول البورصات المصرية .
8 - ملغاة .
9 - العوائد التي تحصل عليها الأشخاص الاعتبارية عن الأوراق المالية وشهادات الإيداع التي يصدرها البنك المركزي المصري أو الإيرادات الناتجة عن التعامل فيها وذلك استثناء من حكم المادة (56) من هذا القانون .
10 - توزيعات الأرباح التي تحصل عليها الشركة الأم أو الشركة القابضة من الشركات التابعة المقيمة وغير المقيمة بعد إضافة نسبة (10%) من قيمة هذه التوزيعات إلى الوعاء الخاضع للضريبة للشركة الأم أو القابضة مقابل التكاليف غير واجبة الخصم ، وذلك بشرط :
(أ) ألا تقل نسبة مساهمة الشركة الأم أو القابضة عن (25%) من رأسمال الشركة التابعة أو حقوق التصويت .
(ب) ألا تقل مدة حيازة الشركة الأم أو القابضة لتلك النسبة عن سنتين ، أو أن تلتزم بالاحتفاظ بهذه النسبة لمدة سنتين من تاريخ اقتناء الأسهم أو حقوق التصويت .
11 - أرباح شركات استصلاح أو استزراع الأراضي لمدة عشر سنوات اعتبارًا من تاريخ بدء مزاولة النشاط أو بدء الإنتاج ، حسب الأحوال ، وفقًا للقواعد التي تحددها اللائحة التنفيذية لهذا القانون .
12 - أرباح شركات الإنتاج الداجني وتربية النحل وحظائر تربية المواشي وتسمينها ومزارع صيد الأسماك ومزارع الأسماك لمدة عشر سنوات من تاريخ مزاولة النشاط .
13 - الأرباح الرأسمالية الناتجة عن التسويات التي تتم على مديونيات شركات قطاع الأعمال العام أو الشركات التي تمتلك الدولة فيها ما لا يقل عن (51%) من رأسمالها وذلك في إطار تسويات ديون هذه الشركات لدى البنوك وغيرها من الجهات الدائنة ، مقابل نقل ملكية كل أراضيها أو بعضها ، ويكون الإعفاء في هذه الحالة في حدود نسبة ما تمتلكه الدولة في رأسمال هذه الشركات .
14 - أرباح صناديق الاستثمار في أدوات الدين وأرباح صناديق الاستثمار القابضة في الأدوات ذاتها أو في صناديق الاستثمار في هذه الأدوات المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وفي حدود الغرض المرخص لها به ، وما يحصل عليه حملة الوثائق من عائد هذه الصناديق ، وذلك كله بشرط ألا تزيد استثمارات الصندوق في الودائع البنكية على (10%) من متوسط جملة استثماراته سنويًا ، وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون .
15 - أرباح صناديق الاستثمار في الأسهم المقيدة في بورصة الأوراق المالية المصرية ، وأرباح صناديق الاستثمار القابضة في الأسهم ذاتها أو في صناديق الاستثمار في هذه الأسهم في هذه المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وما تحصل عليه هذه الصناديق من توزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه الصناديق القابضة المستثمر فيها الصناديق من توزيعات وعوائد التي تحصل عليها صناديق الاستثمار فيها من عوائد ودائعها البنكية ، وذلك كله بشرط أن تقتصر محفظة الأسهم على أسهم الشركات المقيدة في بورصة الأوراق المالية المصرية ، وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون وفي حدود الغرض المرخص لها به .
16 - أرباح صناديق وشركات رأس المال المخاطر المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وفي حدود الغرض المرخص لها به ، وما تحصل عليه من توزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه من عوائد على ودائعها البنكية ، وذلك كله بالشروط الآتية :
(أ) ألا تقل نسبة الاستثمارات الناشئة في شركات مقيمة وغير مقيدة في بورصة الأوراق المالية المصرية عن (80%) من إجمالي الاستثمارات في نهاية فترة تخصيص الاستثمارات المنصوص عليها في مذكرة المعلومات أو نشرة الاكتتاب ، بحسب الأحوال .
(ب) ألا تتجاوز الرافعة التمويلية بالدين نسبة (20%) من إجمالي الاستثمارات .
ولا يسرى هذا الإعفاء على أية إيرادات أو أرباح للصناديق والشركات المشار إليها من المصادر الأخرى ، وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون .
17 - أرباح صناديق الاستثمار الخيرية المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وفي حدود الغرض المرخص لها به ، وما تحصل عليه هذه الصناديق من توزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه من عوائد على ودائعها البنكية ، وذلك كله بشرط أن يتم استخدام عوائد استثمار هذه الصناديق في الأنشطة الخيرية المنشأة من أجلها ، وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون .
18 - أرباح صناديق الاستثمار العقاري المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وفي حدود الغرض المرخص لها به ، وما تحصل عليه من إيرادات ثروة عقارية وتوزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه من عوائد على ودائعها البنكية ، وذلك كله بالشروط الآتية :
(أ) أن يستثمر الصندوق أمواله في أسهم شركات أو صناديق عقارية أو عقارات مبنية بنسبة لا تقل عن (80%) من متوسط جملة استثماراته سنويًا .
(ب) أن يتكون (80%) من إيرادات الصندوق من مقابل تأجير أصول عقارية وتوزيعات أرباح من أسهم شركات عقارية ، وأرباح رأسمالية من بيع أصول ثابتة أو أرباح رأسمالية محققة من بيع أسهم شركات عقارية ، وأرباح وعوائد وتوزيعات الاستثمار التي يحصل عليها الصندوق من صناديق عقارية أخرى .
(ج) ألا يمارس نشاط التطوير العقاري أو المقاولات .
وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون .
وفي تطبيق أحكام البنود أرقام (14 ، 15 ، 16 ، 17 ، 18) من هذه المادة يستبعد ما يحصل عليه الشخص الطبيعي أو الشخص الاعتباري المقيم من حملة الوثائق من وعاء الضريبة الخاضع لها هذا الشخص ، بعد خصم التكاليف المتعلقة بها ، وفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
ولا يجوز أن يترتب على الإعفاء من الضريبة المنصوص عليه في هذا القانون أو في أي قانون آخر ترحيل الخسائر لسنوات تالية .
