15 - أرباح صناديق الاستثمار في الأسهم المقيدة في بورصة الأوراق المالية المصرية ، وأرباح صناديق الاستثمار القابضة في الأسهم ذاتها أو في صناديق الاستثمار في هذه الأسهم في هذه المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وما تحصل عليه هذه الصناديق من توزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه الصناديق القابضة المستثمر فيها الصناديق من توزيعات وعوائد التي تحصل عليها صناديق الاستثمار فيها من عوائد ودائعها البنكية ، وذلك كله بشرط أن تقتصر محفظة الأسهم على أسهم الشركات المقيدة في بورصة الأوراق المالية المصرية ، وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون وفي حدود الغرض المرخص لها به .
16 - أرباح صناديق وشركات رأس المال المخاطر المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وفي حدود الغرض المرخص لها به ، وما تحصل عليه من توزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه من عوائد على ودائعها البنكية ، وذلك كله بالشروط الآتية :
(أ) ألا تقل نسبة الاستثمارات الناشئة في شركات مقيمة وغير مقيدة في بورصة الأوراق المالية المصرية عن (80%) من إجمالي الاستثمارات في نهاية فترة تخصيص الاستثمارات المنصوص عليها في مذكرة المعلومات أو نشرة الاكتتاب ، بحسب الأحوال .
(ب) ألا تتجاوز الرافعة التمويلية بالدين نسبة (20%) من إجمالي الاستثمارات .
ولا يسرى هذا الإعفاء على أية إيرادات أو أرباح للصناديق والشركات المشار إليها من المصادر الأخرى ، وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون .
17 - أرباح صناديق الاستثمار الخيرية المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وفي حدود الغرض المرخص لها به ، وما تحصل عليه هذه الصناديق من توزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه من عوائد على ودائعها البنكية ، وذلك كله بشرط أن يتم استخدام عوائد استثمار هذه الصناديق في الأنشطة الخيرية المنشأة من أجلها ، وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون .
18 - أرباح صناديق الاستثمار العقاري المنشأة وفقًا لقانون سوق رأس المال المشار إليه ، وفي حدود الغرض المرخص لها به ، وما تحصل عليه من إيرادات ثروة عقارية وتوزيعات وأرباح رأسمالية ، وكذلك ما تحصل عليه من عوائد على ودائعها البنكية ، وذلك كله بالشروط الآتية :
(أ) أن يستثمر الصندوق أمواله في أسهم شركات أو صناديق عقارية أو عقارات مبنية بنسبة لا تقل عن (80%) من متوسط جملة استثماراته سنويًا .
(ب) أن يتكون (80%) من إيرادات الصندوق من مقابل تأجير أصول عقارية وتوزيعات أرباح من أسهم شركات عقارية ، وأرباح رأسمالية من بيع أصول ثابتة أو أرباح رأسمالية محققة من بيع أسهم شركات عقارية ، وأرباح وعوائد وتوزيعات الاستثمار التي يحصل عليها الصندوق من صناديق عقارية أخرى .
(ج) ألا يمارس نشاط التطوير العقاري أو المقاولات .
وذلك كله مع عدم الإخلال بأحكام المادة (58) من هذا القانون .
وفي تطبيق أحكام البنود أرقام (14 ، 15 ، 16 ، 17 ، 18) من هذه المادة يستبعد ما يحصل عليه الشخص الطبيعي أو الشخص الاعتباري المقيم من حملة الوثائق من وعاء الضريبة الخاضع لها هذا الشخص ، بعد خصم التكاليف المتعلقة بها ، وفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
ولا يجوز أن يترتب على الإعفاء من الضريبة المنصوص عليه في هذا القانون أو في أي قانون آخر ترحيل الخسائر لسنوات تالية .
