    IF v_art_body <> $vb105_15$تخضع للضريبة بسعر 20% المبالغ التى يدفعها أصحاب المنشآت الفردية والأشخاص الاعتبارية المقيمة فى مصر والجهات غير المقيمة التى لها منشأة دائمة فى مصر لغير المقيمين فى مصر وذلك دون خصم أية تكاليف منها .
وتشمل هذه المبالغ ما يأتى :
1 - العوائد .
2 - الإتاوات .
3 - مقابل الخدمات ، ولا يعتبر من قبيل مقابل الخدمات نصيب المنشأة الدائمة العاملة فى مصر من المصروفات الإدارية ومصروفات الرقابة والإشراف التى يتحملها مركزها الرئيسى فى الخارج ، ويجب عند تحديد أرباح المنشأة الدائمة ألا يزيد ما يعتمد ضمن المصروفات الإدارية ومصروفات الرقابة والإشراف التى يتحملها المركز الرئيسى فى الخارج على 10% من صافى الربح الضريبى للمنشأة وعلى ألا تتضمن المصروفات المحملة فى حدود هذه النسبة أية أتاوات أو عمولات أو أجور مباشرة وبشرط تقديم شهادة من مراقب حسابات المركز الرئيسى معتمدة وموثقة .
4 - مقابل نشاط رياضى أو الفنان سواء دفع له مباشرة أو من خلال أى جهة .
وتعفى من الضريبة المنصوص عليها في هذه المادة عوائد القروض والتسهيلات الائتمانية التي تحصل عليها الحكومة ووحدات الإدارة المحلية وغيرها من الأشخاص الاعتبارية العامة من مصادر خارج مصر .
وتلتزم المنشآت والأشخاص والجهات المشار إليها فى الفقرة الأولى من هذه المادة بما فى ذلك الشركات والمنشآت والفروع المقامة وفقًا لأحكام قانون المناطق الاقتصادية ذات الطبيعة الخاصة وكذلك المشروعات المقامة بنظام المناطق الحرة بحجز مقدار الضريبة المستحقة وتوريدها إلى المصلحة فى أول يوم عمل تال لليوم الذى تم فيه حجز الضريبة .
