    IF v_art_body <> $vb105_16$تخضع للضريبة بسعر (10%) دون خصم أية تكاليف توزيعات الأرباح التي تجريها شركات الأموال أو شركات الأشخاص ، بما في ذلك الشركات المقامة بنظام المناطق الاقتصادية ذات الطبيعة الخاصة للشخص الطبيعي غير المقيم والشخص الاعتباري المقيم أو غير المقيم بما في ذلك أرباح الأشخاص الاعتبارية غير المقيمة التي تحققها من خلال منشأة دائمة من خلال منشأة دائمة في مصر ، عدا التوزيعات التي تتم في صورة أسهم مجانية ، ويكون سعر هذه الضريبة (5%) من توزيعات الأرباح إذا كانت الأوراق المالية مقيدة في بورصة الأوراق المالية المصرية دون خصم أي تكاليف .
وفي تطبيق حكم هذه المادة تعامل الشركات المدنية معاملة شركات الأشخاص .
وتعد أرباح الأشخاص الاعتبارية غير المقيمة التي تحققها من خلال منشأة دائمة في مصر موزعة حكمًا خلال ستين يومًا من تاريخ ختام السنة المالية للمنشأة الدائمة .
وتستبعد توزيعات الأرباح التي تحصل عليها الأشخاص الاعتبارية المقيمة من أشخاص اعتبارية مقيمة أخرى وما يقابلها من تكلفة ووعاء الضريبة على أرباح الأشخاص الاعتبارية المنصوص عليها في هذا القانون من الكتاب الثالث من هذا القانون ، وفقًا لما تحدده اللائحة التنفيذية لهذا القانون .
وتخصم من الضريبة المستحقة على التوزيعات المدفوعة لشركة مقيمة مقابل الضريبة المسددة التي حصلت عليها الشركة الموزعة من شركة مقيمة أخرى ، وذلك بالشروط الآتية :
1 - أن يكون الخصم في حدود قيمة التوزيعات منسوبة إلى إجمالي الإيرادات التي حققتها الشركة الموزعة .
2 - إذا زادت نسبة المساهمة في الشركة القائمة بالتوزيع على (25%) من رأسمال الشركة المقيمة أو حقوق التصويت .
3 - ألا تقل مدة حيازة الشركة للأسهم أو الحصص عن سنتين من تاريخ اقتناء الأسهم للشركات المودعة أسهمها وحصصها بإحدى شركات الإيداع والقيد المركزي .
4 - ألا تتجاوز الضريبة المخصومة الضريبة التي يتم استقطاعها على ذات التوزيعات المدفوعة التي يحدد هذا القانون لهذا الخصم طريقة حسابها .
وتحدد اللائحة التنفيذية لهذا القانون قواعد وضوابط الخصم ، وعلى الجهات التي تنفذ المعاملة أن تقوم بحجز الضريبة وتوريدها إلى الإدارة المركزية للخصم والتحصيل تحت حساب الضريبة بالمصلحة في موعد أقصاه خمسة أيام عمل من بداية الشهر التالي للشهر الذي تم فيه التحصيل ، وذلك على النموذج المعد لذلك .
